using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace GisAgentDesktop;
internal sealed class SettingsForm:Form {
 readonly TextBox provider=new(),endpoint=new(),model=new(),key=new(){UseSystemPasswordChar=true};readonly CheckBox proxy=new(){Text="使用系统代理"},tls=new(){Text="固定TLS 1.2"};readonly string? selectedId;JsonObject? existing;
 public SettingsForm(Profile? selected){selectedId=selected?.Id;Text="模型接口设置（Chat Completions兼容）";Size=new Size(650,350);MinimumSize=Size;StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",9);MaximizeBox=false;MinimizeBox=false;
  var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),ColumnCount=2,RowCount=7};table.ColumnStyles.Add(new(SizeType.Absolute,95));table.ColumnStyles.Add(new(SizeType.Percent,100));Controls.Add(table);int row=0;foreach(var (title,box) in new[]{("配置名称",provider),("HTTPS接口",endpoint),("模型ID",model),("API密钥",key)}){table.Controls.Add(new Label{Text=title,AutoSize=true},0,row);box.Dock=DockStyle.Fill;table.Controls.Add(box,1,row++);}var flags=new FlowLayoutPanel{Dock=DockStyle.Fill};flags.Controls.AddRange(new Control[]{proxy,tls});table.Controls.Add(flags,1,4);table.Controls.Add(new Label{Text="密钥只在本机加密保存；已有密钥可留空保持。",AutoSize=true},1,5);var save=new Button{Text="保存配置",AutoSize=true};table.Controls.Add(save,1,6);save.Click+=(_,_)=>Save();AcceptButton=save;
  if(selectedId!=null&&File.Exists(MainForm.ConfigPath)){var cfg=JsonNode.Parse(File.ReadAllText(MainForm.ConfigPath))!;existing=cfg["profiles"]!.AsArray().FirstOrDefault(p=>p?["id"]?.GetValue<string>()==selectedId)?.DeepCloneCompat();}
  provider.Text=existing?["provider"]?.GetValue<string>()??"智谱";endpoint.Text=existing?["endpoint"]?.GetValue<string>()??"https://open.bigmodel.cn/api/paas/v4/chat/completions";model.Text=existing?["model"]?.GetValue<string>()??"glm-5.3-flash";proxy.Checked=existing?["useSystemProxy"]?.GetValue<bool>()??false;tls.Checked=existing?["forceTls12"]?.GetValue<bool>()??true;
 }
 void Save(){try{if(string.IsNullOrWhiteSpace(provider.Text)||string.IsNullOrWhiteSpace(model.Text)||model.Text.Length>120||model.Text.IndexOfAny(new[]{'\r','\n'})>=0)throw new Exception("请填写配置名称和有效模型ID。");if(!Uri.TryCreate(endpoint.Text.Trim(),UriKind.Absolute,out var address)||address.Scheme!="https"||address.UserInfo.Length>0||address.Query.Length>0||address.Fragment.Length>0)throw new Exception("接口须为不含账户、查询参数的完整HTTPS地址。");string encrypted=existing?["encryptedKey"]?.GetValue<string>()??"";if(key.Text.Length>0)encrypted=Vault.Protect(key.Text);if(encrypted.Length==0)throw new Exception("请在本机密钥框填写API密钥。");
  var cfg=File.Exists(MainForm.ConfigPath)?JsonNode.Parse(File.ReadAllText(MainForm.ConfigPath))!.AsObject():new JsonObject{["profiles"]=new JsonArray()};var profiles=cfg["profiles"]!.AsArray();string id=selectedId??Guid.NewGuid().ToString("N");var p=existing?.DeepCloneCompat()??new JsonObject{["id"]=id,["protocol"]="chat",["proxyAddress"]="",["maxTokens"]=4096,["disableThinking"]=true,["timeoutSeconds"]=90};p["provider"]=provider.Text.Trim();p["endpoint"]=endpoint.Text.Trim();p["model"]=model.Text.Trim();p["encryptedKey"]=encrypted;p["useSystemProxy"]=proxy.Checked;p["forceTls12"]=tls.Checked;for(int i=profiles.Count-1;i>=0;i--)if(profiles[i]?["id"]?.GetValue<string>()==id)profiles.RemoveAt(i);profiles.Add(p);cfg["activeId"]=id;
  Directory.CreateDirectory(Path.GetDirectoryName(MainForm.ConfigPath)!);string temp=MainForm.ConfigPath+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,cfg.ToJsonString(new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));File.Move(temp,MainForm.ConfigPath,true);}finally{if(File.Exists(temp))File.Delete(temp);}key.Clear();DialogResult=DialogResult.OK;Close();
 }catch(Exception ex){MessageBox.Show(this,ex.Message,"配置未保存",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
internal static class JsonExtensions {public static JsonObject DeepCloneCompat(this JsonNode value)=>JsonNode.Parse(value.ToJsonString())!.AsObject();}
internal static class Vault {
 [StructLayout(LayoutKind.Sequential)]struct Blob {public int Length;public IntPtr Data;}
 [DllImport("crypt32.dll",SetLastError=true,CharSet=CharSet.Unicode)]static extern bool CryptProtectData(ref Blob input,string? description,IntPtr entropy,IntPtr reserved,IntPtr prompt,int flags,out Blob output);
 [DllImport("kernel32.dll")]static extern IntPtr LocalFree(IntPtr pointer);
 public static string Protect(string secret){if(string.IsNullOrWhiteSpace(secret)||secret.Length>4096||secret.IndexOfAny(new[]{'\r','\n'})>=0)throw new Exception("密钥为空或格式无效。");byte[] bytes=Encoding.UTF8.GetBytes(secret.Trim());var input=new Blob{Length=bytes.Length,Data=Marshal.AllocHGlobal(bytes.Length)};Blob output=default;
  try{Marshal.Copy(bytes,0,input.Data,bytes.Length);if(!CryptProtectData(ref input,null,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero,1,out output))throw new Exception("Windows本机凭据加密失败。");var saved=new byte[output.Length];Marshal.Copy(output.Data,saved,0,saved.Length);return Convert.ToBase64String(saved);}finally{Array.Clear(bytes);for(int i=0;i<input.Length;i++)Marshal.WriteByte(input.Data,i,0);Marshal.FreeHGlobal(input.Data);if(output.Data!=IntPtr.Zero)LocalFree(output.Data);}}
}
